  if (!options.llmRunner || !options.vectorStore || !options.allowedRecordIds || !options.recordedAt) throw new Error("PREPARE_CONTEXT_REQUIRED");
  const filter = { teamId, userId, agentId, sessionId, taskId, sessionKey, allowedRecordIds: options.allowedRecordIds, ...options.relevance };
  const decisions = await batchDedup({ memories: memoriesWithIds, config, llmRunner: options.llmRunner,
    vectorStore: options.vectorStore, embeddingService: options.embeddingService, filter, strict: true });
  const targetIds = [...new Set(decisions.filter(d => d.action === "update" || d.action === "merge").flatMap(d => d.target_ids))];
  if (targetIds.some(id => !options.allowedRecordIds!.includes(id))) throw new Error("TARGET_OUTSIDE_ALLOWLIST");
  const targets = targetIds.length ? await options.vectorStore.queryL1Records({ ...filter, recordIds: targetIds }) : [];
  if (targets.length !== targetIds.length) throw new Error("TARGET_MISSING");
  const records = decisions.filter(d => d.action !== "skip").map(d => {
    const memory = memoriesWithIds.find(m => m.record_id === d.record_id);
    if (!memory) throw new Error("UNKNOWN_DECISION_RECORD");
    const version = Math.max(0, ...targets.filter(t => d.target_ids.includes(t.record_id)).map(t => t.version ?? 0)) + 1;
    return prepareMemoryRecord(memory, d, { sessionKey, sessionId: sessionId!, teamId, userId, agentId, taskId }, options.recordedAt!, version);
  });
